package com.hirain.aiagent.rag.policy;
import com.hirain.aiagent.rag.document.SourceCitationRenderer;import com.hirain.aiagent.rag.model.VehicleKnowledgeEvidence;import java.util.*;import java.util.regex.*;
/** 只接受当前 Request Evidence Map 中的显式 [E数字]；模型自行编造的页码或来源文字不构成引用。 */
public final class CitationGuard {private static final Pattern MARKER=Pattern.compile("\\[E(\\d+)\\]");private final SourceCitationRenderer renderer=new SourceCitationRenderer();public CitationValidationResult validate(String answer,Map<String,?> currentEvidence,boolean required){if(answer==null||answer.isBlank())return CitationValidationResult.fail("KNOWLEDGE_CITATION_INVALID");LinkedHashSet<String> ids=new LinkedHashSet<>();Matcher matcher=MARKER.matcher(answer);while(matcher.find())ids.add("E"+matcher.group(1));if(required&&ids.isEmpty())return CitationValidationResult.fail("KNOWLEDGE_CITATION_INVALID");for(String id:ids)if(currentEvidence==null||!currentEvidence.containsKey(id))return CitationValidationResult.fail("KNOWLEDGE_CITATION_INVALID");String output=answer;List<String> sources=new ArrayList<>();for(String id:ids){Object value=currentEvidence.get(id);if(value instanceof VehicleKnowledgeEvidence evidence)sources.add(renderer.render(id,evidence.documentTitle(),evidence.sourceLocator()));}if(!sources.isEmpty())output=answer+"\n\n"+String.join("\n",sources);return new CitationValidationResult(true,output,"OK",List.copyOf(ids));}}
